import csv, re

rows = list(csv.DictReader(open('documents/bank_checking_2024-12_to_2026-01.csv')))

def cls(r):
    d = r['description']; a = float(r['amount']); date = r['date']
    if re.match(r'ACH CREDIT TESSARO', d):
        if date.startswith('2024'):
            return ('prior_year','Schedule C line 1',
                    'Tessaro inv 1041 received 12/27/2024 — prior-year receipt (cash method → 2024 return), not 2025 gross receipts')
        return ('business_income','Schedule C line 1',
                'Client business receipt - Tessaro (direct ACH); 2025 total 2,400.00+3,100.00+2,150.00+1,750.00 = 9,400.00 = 1099-NEC line 1')
    if re.match(r'PAYHUB PAYOUT', d):
        return ('business_income','Schedule C line 1',
                'PayHub payout (1099-K PSE). Net of retained 2.9% fee; deposit+fees reconstruct 1099-K gross 41,350.00 exactly. Client confirmed Beacon (18,500.00) & Orchard (12,200.00) NECs are also paid via PayHub → inside 1099-K, NOT added on top (dedupe per Schedule C instructions)')
    if re.match(r'DIRECT DEP LARKSPUR', d):
        return ('other_schedule','',
                'W-2 wages (net payroll deposit) — Form 1040 line 1a; W-2 gross 24,800.00. Never Schedule C')
    if re.match(r'IRS USATAXPYMT', d):
        return ('tax_payment','',
                '2025 federal estimated tax (1,500.00+2,500.00+2,500.00 = 6,500.00) — Form 1040 line 26 credit; not a Schedule C expense')
    if re.match(r'BLUE CROSS', d):
        return ('other_schedule','',
                'Self-employed health insurance premiums, 380.00 × 8 mo May–Dec = 3,040.00 — Schedule 1 line 17, NOT Schedule C line 15')
    if re.match(r'HISCOX', d):
        return ('business_expense','15','Professional liability = business insurance (not health) — Schedule C line 15')
    if re.match(r'CAPITAL FACTORY', d):
        return ('business_expense','20b','Coworking membership (office space) 350.00 × 8 mo = 2,800.00 — Schedule C line 20b')
    if re.match(r'APPLE.COM/BILL MACBOOK', d):
        return ('business_expense','27a',
                'MacBook Pro 2,149.00 — de minimis safe harbor (≤2,500) elected → line 27a, not line 13; business-use % undocumented (client gave none) — 100% ASSUMED, flagged')
    if re.match(r'SOUTHWEST AIR 526 AUS-SFO', d):
        return ('business_expense','24a','Airfare for DesignWeek SF conference trip (business travel away from home) — Schedule C line 24a')
    if re.match(r'HOTEL ZEPHYR', d):
        return ('business_expense','24a','Lodging during DesignWeek SF business trip — Schedule C line 24a')
    if re.match(r'DESIGNWEEK', d):
        return ('business_expense','27a','Conference registration = professional development — Schedule C line 27a')
    if re.match(r'SQ \*MARINA DELI', d):
        return ('business_expense','24b','Business travel meal (SF trip): 64.00 × 50% = 32.00 — Schedule C line 24b')
    if re.match(r'TARTINE', d):
        return ('business_expense','24b','Business travel meal (SF trip): 126.00 × 50% = 63.00 — Schedule C line 24b')
    if re.match(r'SOUTHWEST AIR 118 AUS-DEN', d):
        return ('personal','','Client confirmed personal trip (cousin\'s wedding) — no deduction; Pub 463 personal travel')
    if re.match(r'VENMO', d):
        return ('personal','','Wedding gift — personal expense §262(a)')
    if re.match(r'T-MOBILE', d):
        return ('personal','25',
                'Cell service: client estimates 60% business (not documented); line 25 share = 85.00×0.60 = 51.00/mo, 612.00/yr; balance personal — ESTIMATE flagged')
    if re.match(r'SPECTRUM', d):
        return ('personal','25',
                'Home internet: client estimates 60% business (not documented); line 25 share = 70.00×0.60 = 42.00/mo, 504.00/yr — ESTIMATE flagged')
    if re.match(r'FIGMA', d):
        return ('business_expense','27a','Design software subscription 45.00 × 12 = 540.00 — software subscriptions go to line 27a')
    if re.match(r'ADOBE', d):
        return ('business_expense','27a','Design software subscription 59.99 × 12 = 719.88 — software subscriptions go to line 27a')
    if re.match(r'ZELLE TO: M. OKAFOR RENT', d):
        return ('personal','','Home rent 1,650.00 × 12 = 19,800.00 — personal living expense §262(a); home office NOT claimed')
    return ('personal','','Personal living expense §262(a)')

out = [['date','description','amount','classification','schedule_c_line','note']]
counts = {}
for r in rows:
    c, line, note = cls(r)
    counts[c] = counts.get(c,0)+1
    out.append([r['date'], r['description'], r['amount'], c, line, note])

w = csv.writer(open('deliverable/classification.csv','w',newline=''))
w.writerows(out)
print('rows written:', len(out)-1)
for k,v in sorted(counts.items()): print(f'{k}: {v}')

# reconciliation of the money
bi = sum(float(r[2]) for r in out[1:] if r[3]=='business_income')
be = -sum(float(r[2]) for r in out[1:] if r[3]=='business_expense')
print('business_income received:', round(bi,2), '(+1,199.15 retained fees = 50,750.00 line 1)')
print('business_expense charged:', round(be,2))
ps = [round(-sum(float(r[2]) for r in out[1:] if r[1].startswith(p) and r[0].startswith('2025')),2) for p in ('T-MOBILE','SPECTRUM','BLUE CROSS','IRS ZELLE'[:0] or 'IRS USATAXPYMT','ZELLE TO: M. OKAFOR RENT','ORANGETHEORY','NETFLIX','DEBIT CARD H-E-B')]
print('annual personal/other aggregates [tmobile, spectrum, bcbs, est-tax, rent, gym, netflix]:', ps, 'HEB:', ps[7] if len(ps)>7 else '')
EOF

